                    for (int l = painters[k].first; l <= painters[k].second; l++) {
                        sections[l] = 1;
                    }
                }
            }
            maxSections = max(maxSections, count(sections.begin(), sections.end(), 1));
        }
    }

    cout << maxSections << endl;

    return 0;
}

